  const barytone = 'Barytone';
  const acute = 'Acute on the last syllable';

  const upsilonRule = 'Herodian classes words in -υψ as barytone.';
  const omegaNounRule = 'Herodian classes polysyllabic names and nouns in -ωψ as barytone.';
  const omegaAdjectiveRule = 'Adjectives in -ωψ generally have a final acute. Herodian also lists exceptions.';
  const entries = [
    ['Κίνυψ', barytone, upsilonRule + ' He gives Κίνυψ as both a harbor and a river.'],
    ['Χάλυψ', barytone, upsilonRule + ' Χάλυψ names a people near the Thermodon.'],
    ['Ἄρυψ', barytone, upsilonRule + ' He also gives the one-syllable form Ῥύψ.'],
    ['Ῥύψ', 'Monosyllabic variant', 'Herodian gives Ῥύψ as a one-syllable variant of Ἄρυψ.'],
    ['κώληψ', barytone, 'The only example in -ηψ that Herodian gives is κώληψ.'],
    ['Κύκλωψ', barytone, omegaNounRule],
    ['Ἄλμωψ', barytone, omegaNounRule + ' The passage connects this name with Ἀλμωπία in Macedonia.'],
    ['ἴωψ', barytone, 'Herodian lists ἴωψ among the barytone examples and identifies it as a fish.'],
    ['μώλωψ', barytone, omegaNounRule],
    ['μονώψ', acute, omegaAdjectiveRule + ' μονώψ means one-eyed.'],
    ['κελαινώψ', acute, omegaAdjectiveRule],
    ['τυφλώψ', acute, omegaAdjectiveRule],
    ['γλαυκώψ', acute, omegaAdjectiveRule + ' The passage illustrates it with γλαυκῶπες δράκοντες.'],
    ['εὐώψ', acute, omegaAdjectiveRule + ' Herodian cites εὐῶπα παρειάν from Sophocles.'],
    ['παραβλώψ', acute, omegaAdjectiveRule + ' Herodian cites an inflected form from the Iliad (Ι 503).'],
    ['ἑλίκωψ', barytone, 'Herodian singles out this word as barytone alongside μύωψ and νυκτάλωψ.'],
    ['μύωψ', barytone, 'Herodian singles out μύωψ as barytone, grouping it with Κύκλωψ.'],
    ['νυκτάλωψ', barytone, 'Herodian singles out this word as barytone alongside ἑλίκωψ and μύωψ.'],
    ['κέρκωψ', barytone, 'Herodian groups κέρκωψ, “the crafty one,” with Κύκλωψ.'],
    ['εὐρώψ', 'Final acute, reported by some', 'Herodian qualifies the accent of εὐρώψ with “as some say.”']
  ];

  const fold = word => word.trim().normalize('NFD').replace(/\p{Mark}/gu, '').toLowerCase();
  const index = new Map(entries.map(entry => [fold(entry[0]), entry]));
  const input = document.querySelector('#word');
  const form = document.querySelector('#form');
  const accent = document.querySelector('#accent');
  const explanation = document.querySelector('#explanation');

  function show() {
    const query = fold(input.value);
    const match = index.get(query);
    form.hidden = !match;
    form.textContent = match ? match[0] : '';
    accent.textContent = match ? match[1] : '';
    if (match) {
      explanation.textContent = match[2] + (match[1] === barytone ? ' Its accent is before the final syllable.' : '');
    } else {
      explanation.textContent = query
        ? 'This lookup covers the examples in passage 1.247. Try one of the words above.'
        : 'Choose an example or type a word from the passage.';
    }
  }

  document.querySelector('#look').addEventListener('click', show);
  input.addEventListener('keydown', event => {
    if (event.key === 'Enter') show();
  });
  document.querySelector('#clear').addEventListener('click', () => {
    input.value = '';
    show();
    input.focus();
  });
  for (const button of document.querySelectorAll('[data-word]')) {
    button.addEventListener('click', () => {
      input.value = button.dataset.word;
      show();
    });
  }
})();

