(() => {
  const select = selector => document.querySelector(selector);
  const input = select('#inp');
  const keepBreath = select('#keepBreath');
  const useAttestedBreathing = select('#stripAll');
  const acute = 'oxytone';
  const barytone = 'barytone';

  const categories = [
    [acute, 'Patronymics or words formed on the patronymic pattern take a final acute.',
      ['Πριαμίς', 'Τανταλίς', 'Τυνδαρίς', 'Ἑλικωνίς', 'Αὐσονίς', 'Βιστονίς', 'Ἀβαντίς', 'Εὐξαντίς']],
    [acute, 'Diminutives in -ις take a final acute when the derivation has the same number of syllables.',
      ['θεραπαινίς', 'ἑταιρίς', 'λυρίς']],
    [barytone, 'These examples from barytone futures keep the accent off the last syllable.',
      ['ποίησις', 'γνῶσις', 'πρᾶξις', 'ἕξις', 'μέμψις', 'λέξις']],
    [acute, 'Herodian lists these disyllabic examples in -βις with a final acute.',
      ['λαβίς', 'Λεσβίς', 'βαλβίς']],
    [barytone, 'The passage gives these forms in the barytone group.',
      ['ἶβις', 'Ἄρβις', 'Ἄραβις', 'Νίβις', 'Τάβις', 'Νάρβις', 'Ζόμβις', 'Χέμβις']],
    [acute, 'These longer paronyms or adjectives in -βις take a final acute.',
      ['Νιοβίς', 'Λυκαμβίς', 'Περραιβίς', 'Κανωβίς', 'Ἐρεμβίς', 'Τορρηβίς']],
    [barytone, 'Herodian treats ἄσις as an exception under the rule pairing it with ἄση.',
      ['ἄσις']],
    [barytone, 'Herodian treats Ἶφις, derived from ἶφι, as barytone.',
      ['Ἶφις']],
    ['barytone or oxytone', 'Herodian cites Hesiod for barytone ἅψις and uses Homer’s ἁψῖσι as evidence of long ι in oxytone ἁψίς.',
      ['ἅψις', 'ἁψίς']]
  ];

  const plain = word => word.normalize('NFD').replace(/\p{Mark}/gu, '');
  const fold = word => plain(word).toLowerCase().replace(/σ$/u, 'ς');
  const index = new Map();
  for (const [accent, rule, examples] of categories) {
    for (const example of examples) {
      const key = fold(example);
      if (!index.has(key)) index.set(key, {accent, rule, forms: []});
      index.get(key).forms.push(example);
    }
  }

  function ending(word) {
    return ['-βις', '-σις', '-ις'].find(suffix => fold(word).endsWith(suffix.slice(1))) || '(other)';
  }

  function detectedAccent(word) {
    const nfd = word.normalize('NFD');
    if (nfd.includes('\u0301')) return 'acute';
    if (nfd.includes('\u0342')) return 'circumflex';
    if (nfd.includes('\u0300')) return 'grave';
    return 'none';
  }

  function format(form, typed) {
    const typedLetters = Array.from(plain(typed));
    const typedUnits = typed.normalize('NFD').match(/\P{Mark}\p{Mark}*/gu);
    const formUnits = form.normalize('NFD').match(/\P{Mark}\p{Mark}*/gu);
    return formUnits.map((unit, index) => {
      const uppercase = /\p{Lu}/u.test(typedLetters[index] || '');
      const base = uppercase ? unit[0].toUpperCase() : unit[0];
      const marks = unit.slice(1).replace(/[\u0313\u0314]/gu, '');
      const attestedBreathing = unit.match(/[\u0313\u0314]/u)?.[0] || '';
      const typedBreathing = typedUnits[index]?.match(/[\u0313\u0314]/u)?.[0] || '';
      const preferredBreathing = useAttestedBreathing.checked
        ? attestedBreathing : typedBreathing || attestedBreathing;
      const breathing = keepBreath.checked ? preferredBreathing : '';
      return base + breathing + marks;
    }).join('').normalize('NFC');
  }

  function render() {
    const text = input.value;
    const match = Array.from(text.matchAll(/\p{Script=Greek}[\p{Script=Greek}\p{Mark}]*/gu)).at(-1);
    const word = match?.[0] || '';
    const entry = index.get(fold(word));
    select('#lastWord').textContent = word || '—';
    select('#ending').textContent = word ? ending(word) : '—';
    select('#syll').textContent = word ? String((plain(word).match(/[αεηιουω]/giu) || []).length) : '—';
    select('#nowAccent').textContent = word ? detectedAccent(word) : '—';
    select('#accentGuess').textContent = entry?.accent || '—';
    select('#ruleBox').textContent = entry?.rule || (word ? 'No matching example in this passage.' : '—');
    select('#out').textContent = entry ? entry.forms.map(form => {
      const next = format(form, word);
      return text.slice(0, match.index) + next + text.slice(match.index + word.length);
    }).join('\n') : word ? text : '—';
  }

  select('#btnGo').addEventListener('click', render);
  input.addEventListener('keydown', event => {
    if (event.key === 'Enter') render();
  });
  select('#btnClear').addEventListener('click', () => {
    input.value = '';
    render();
    input.focus();
  });
  for (const button of document.querySelectorAll('.chip')) {
    button.addEventListener('click', () => {
      input.value = button.dataset.ex;
      render();
      input.focus();
    });
  }
  keepBreath.addEventListener('change', render);
  useAttestedBreathing.addEventListener('change', render);
  input.value = 'ποιησις';
  render();
})();

