.chips{display:flex; gap:8px; flex-wrap:wrap}
.chip{padding:6px 10px; border-radius:999px; font-size:12px; color:var(--muted)}
.chip:hover{color:var(--ink)}

.grid{display:grid; grid-template-columns:repeat(12, 1fr); gap:12px; margin-top:12px}
.card{grid-column:span 12; background:var(--card); border:1px solid var(--line); border-radius:14px; padding:12px}
@media (min-width: 860px){
  .card:nth-child(1){grid-column:span 4}
  .card:nth-child(2){grid-column:span 8}
  .card:nth-child(3){grid-column:span 12}
}

.card h2{margin:0 0 10px 0; font-size:14px; color:var(--ink)}

.mono{font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace}
.box{background:#0c0f1f; border:1px solid var(--line); border-radius:12px; padding:10px; min-height:44px; display:flex; align-items:center}

.row2{display:grid; grid-template-columns: 1fr; gap:10px}
@media (min-width: 860px){
  .row2{grid-template-columns: 220px 1fr}
}

.lbl{color:var(--muted); font-size:12px; margin-bottom:4px}
.big{font-size:18px; font-weight:650}

.controls{display:flex; gap:14px; flex-wrap:wrap; margin-top:10px}
.toggle{color:var(--muted); font-size:12px; display:flex; gap:8px; align-items:center}
.toggle input{transform:translateY(1px)}

.hint{margin-top:8px; color:var(--faint); font-size:12px; line-height:1.35}

.lab{display:grid; gap:8px}
.labrow{display:grid; grid-template-columns: 160px 1fr; gap:10px; align-items:center}

.notes{margin-top:12px; border:1px solid var(--line); border-radius:12px; padding:10px; background:rgba(12,15,31,.55)}
.notes summary{cursor:pointer; color:var(--accent); font-size:13px}
.noteBody{color:var(--muted); font-size:13px; line-height:1.4}

.kbd{padding:1px 6px; border:1px solid var(--line); border-radius:8px; background:#0c0f1f}

.ftr{margin-top:10px; color:var(--faint); font-size:12px}

.badge{display:inline-block; padding:2px 8px; border-radius:999px; border:1px solid var(--line); font-size:12px; color:var(--muted)}

